# Generated by build.py from recipe.yml for recipe http-expire-a-token-mid-session. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'control-token.txt'), "control-token-0123456789abcdefghij`n")
[IO.File]::WriteAllText((Join-Path $PWD 'stale-token.txt'), "tok-from-yesterday")
[IO.File]::WriteAllText((Join-Path $PWD 'bearer.json'), "{`"user`":`"`",`"password`":`"tok-2`"}")
[IO.File]::WriteAllText((Join-Path $PWD 'client.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The client: calls the API with the token it keeps in a file. With no token, it logs in for`n# one; when the call is answered 401, it logs in again for a new token and retries once.`n# Usage: sh client.sh <base URL> <user:password> <token file>`nbase=`$1`nuser=`$2`ncache=`$3`n`nlogin() {`n  answer=`$(curl -sSf --cacert server.pem -u `"`$user`" `"`${base}token?service=surl`") || exit `$?`n  old=`$(cat `"`$cache`" 2>/dev/null)`n  printf '%s' `"`$answer`" | sed 's/^{`"token`":`"\([^`"]*\)`".*/\1/' > `"`$cache`"`n  if [ -z `"`$old`" ]; then echo `"login: token issued`"`n  elif [ `"`$old`" = `"`$(cat `"`$cache`")`" ]; then echo `"login: same token`"`n  else echo `"login: new token`"; fi`n}`n`ncall() {`n  curl -s --cacert server.pem --oauth2-bearer `"`$(cat `"`$cache`")`" -o api.out -w `"%{http_code}`" `"`${base}v2/`"`n}`n`ntest -s `"`$cache`" || login`nstatus=`$(call)`necho `"call: `$status`"`nif [ `"`$status`" = 401 ]; then`n  login`n  status=`$(call)`n  echo `"retry: `$status`"`nfi`ntest `"`$status`" = 200`n")
[IO.File]::WriteAllText((Join-Path $PWD 'logins.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Polls the control endpoint, at most 25 times 0.2 s apart, until it holds at least <count>`n# judged logins, then prints one line per login: account, mechanism, accepted or refused.`n# Usage: sh logins.sh <control URL> <count>`nauth=`"Authorization: Bearer `$(head -n 1 control-token.txt)`"`ntries=0`nwhile :; do`n  events=`$(curl -s -H `"`$auth`" `"`$1/v1/events?kind=login_judged`")`n  count=`$(printf '%s' `"`$events`" | grep -o '`"kind`":`"login_judged`"' | wc -l | tr -d ' ')`n  [ `"`$count`" -ge `"`$2`" ] && break`n  tries=`$((tries + 1))`n  [ `"`$tries`" -ge 25 ] && break`n  sleep 0.2`ndone`nprintf '%s' `"`$events`" | grep -o '`"account`":`"[^`"]*`",`"mechanism`":`"[^`"]*`",`"is_accepted`":[a-z]*' \`n  | sed -e 's/`"account`":`"\([^`"]*\)`",`"mechanism`":`"\([^`"]*\)`",`"is_accepted`":/\1 \2 /' -e 's/ true`$/ accepted/' -e 's/ false`$/ refused/'`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--user', 'app:s3cret', '--control', 'http://127.0.0.1:8081', '--control-token-file', 'control-token.txt', 'oci://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh client.sh https://127.0.0.1:8080/ app:s3cret token.txt && curl -s -o NUL -w "reset: %{response_code}\n" -X POST -H "Authorization: Bearer control-token-0123456789abcdefghij" http://127.0.0.1:8081/v1/reset && sh client.sh https://127.0.0.1:8080/ app:s3cret token.txt } finally { Stop-Process $server0 }
